package com.bookeat.reservation.service;
import com.bookeat.reservation.dto.*;
import com.bookeat.reservation.entity.*;
import com.bookeat.reservation.enums.*;
import com.bookeat.reservation.repository.*;
import com.bookeat.reservation.mapper.BookingMapper;
import com.bookeat.commerce.service.*;
import com.bookeat.common.audit.AuditService;
import com.bookeat.common.response.PageResponse;
import com.bookeat.exception.*;
import com.bookeat.user.repository.UserRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import org.springframework.data.domain.*;
import java.time.*;
import java.util.*;
@Service @RequiredArgsConstructor @Transactional
public class CorporateBookingService {
    private final CorporateAccountRepository accounts;private final CorporateBookingRepository corporate;private final CorporateGuestRepository guests;
    private final ReservationRepository reservations;private final ReservationService booking;private final BookingMapper mapper;private final CommerceAccess access;private final IdempotencyService idempotency;private final UserRepository users;private final Clock clock;private final AuditService audit;private final List<BookingCommitmentGuard> commitments;
    public List<BookingResponses.Corporate> create(UUID actor,String key,BookingRequests.Corporate q){UUID series=idempotency.execute(actor,"corporate-booking",key,q,()->{UUID c=access.customer(actor);var r=access.lock(q.reservation().restaurantId());access.requireService(r,com.bookeat.restaurant.enums.ServiceType.DINE_IN);if(r.getTimezone()==null)throw new ApiException(ErrorCode.SERVICE_NOT_AVAILABLE);access.require((q.corporateAccountId()==null)!=(q.account()==null));CorporateAccount account;
        if(q.corporateAccountId()!=null)account=accounts.findByIdAndOwnerCustomerId(q.corporateAccountId(),c).filter(CorporateAccount::isActive).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));else{var a=q.account();account=new CorporateAccount();account.setOwnerCustomerId(c);account.setCompanyName(a.companyName().trim());account.setGstNumber(a.gstNumber());account.setBillingAddress(a.billingAddress());account.setContactPersonName(a.contactPersonName());account.setContactEmail(a.contactEmail().trim().toLowerCase(Locale.ROOT));account.setContactPhone(a.contactPhone());account.setActive(true);accounts.saveAndFlush(account);}
        List<OffsetDateTime> starts;try{starts=BookingRules.occurrences(q.reservation().startsAt(),ZoneId.of(r.getTimezone()),q.recurrenceType(),q.occurrences(),q.interval());}catch(IllegalArgumentException ex){throw new ApiException(ErrorCode.VALIDATION_FAILED);}UUID sid=UUID.randomUUID();
        for(var start:starts){var in=q.reservation();var reservation=booking.createLocked(actor,new BookingRequests.Create(in.restaurantId(),in.tableId(),start,in.guestCount(),in.specialRequest()),BookingType.CORPORATE);var b=new CorporateBooking();b.setCorporateAccountId(account.getId());b.setReservationId(reservation.getId());b.setRestaurantId(r.getId());b.setOrganizerCustomerId(c);b.setSeriesId(sid);b.setBudgetLimit(q.budgetLimit());b.setBillingType(q.billingType());b.setRecurrenceType(q.recurrenceType());b.setRecurrenceRule("{\"occurrences\":"+q.occurrences()+",\"interval\":"+q.interval()+"}");b.setInvoiceRequired(q.invoiceRequired());corporate.saveAndFlush(b);}return sid;});return corporate.findBySeriesIdOrderByCreatedAtAscIdAsc(series).stream().filter(b->b.getOrganizerCustomerId().equals(access.customer(actor))).map(this::response).toList();}
    @Transactional(readOnly=true) public PageResponse<BookingResponses.Corporate> list(UUID actor,int page,int size){return PageResponse.from(corporate.findByOrganizerCustomerId(access.customer(actor),PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"createdAt","id"))).map(this::response));}
    @Transactional(readOnly=true) public BookingResponses.Corporate get(UUID actor,UUID id){return response(owned(actor,id));}
    public BookingResponses.GuestInvite addGuest(UUID actor,UUID id,long version,BookingRequests.Guest q){var b=lock(actor,id);access.version(b.getVersion(),version);var r=reservations.findById(b.getReservationId()).orElseThrow();if(!BookingRules.editable(r.getStatus())||!clock.instant().isBefore(r.getStartsAt()))throw new ApiException(ErrorCode.BOOKING_STATE_INVALID);if(guests.countByCorporateBookingIdAndStatusNot(id,GuestStatus.REMOVED)+1>=r.getGuestCount())throw new ApiException(ErrorCode.GROUP_FULL);
        String token=InviteTokens.issue();var g=new CorporateGuest();g.setCorporateBookingId(id);g.setName(q.name());g.setEmail(q.email().trim().toLowerCase(Locale.ROOT));g.setPhone(q.phone());g.setEmployeeCode(q.employeeCode());g.setStatus(GuestStatus.INVITED);g.setInviteHash(InviteTokens.hash(token));g.setInviteExpiresAt(r.getStartsAt());guests.save(g);b.setChangeSequence(b.getChangeSequence()+1);corporate.flush();audit.record(actor,"CORPORATE_GUEST_INVITED","CorporateBooking",id,null);String uri="bookeat://corporate/join/"+token;return new BookingResponses.GuestInvite(mapper.guest(g),new BookingResponses.Invitation(token,uri,uri,g.getInviteExpiresAt()));}
    public BookingResponses.Guest join(UUID actor,String token){String hash=InviteTokens.hash(token);var bookingId=guests.bookingIdByInvite(hash).orElseThrow(()->new ApiException(ErrorCode.INVITE_INVALID));UUID rid=corporate.restaurantId(bookingId).orElseThrow();access.lock(rid);var g=guests.findByInviteHash(hash).orElseThrow();var b=corporate.findById(g.getCorporateBookingId()).orElseThrow();var r=reservations.findById(b.getReservationId()).orElseThrow();var u=users.findById(actor).orElseThrow();UUID c=access.customer(actor);
        if(!u.isEmailVerified()||!u.getEmail().equalsIgnoreCase(g.getEmail())||!clock.instant().isBefore(g.getInviteExpiresAt())||!BookingRules.editable(r.getStatus())||g.getStatus()==GuestStatus.REMOVED)throw new ApiException(ErrorCode.INVITE_INVALID);if(g.getCustomerId()!=null&&!g.getCustomerId().equals(c))throw new ApiException(ErrorCode.INVITE_INVALID);g.setCustomerId(c);g.setStatus(GuestStatus.JOINED);b.setChangeSequence(b.getChangeSequence()+1);corporate.flush();return mapper.guest(g);}
    public BookingResponses.Corporate change(UUID actor,UUID id,BookingRequests.CorporateChange q){var b=lock(actor,id);for(var g:commitments)g.checkCorporateBudget(id,q.budgetLimit());var r=booking.lockOwned(actor,b.getReservationId());booking.changeLocked(actor,r,q.reservation());b.setBudgetLimit(q.budgetLimit());b.setBillingType(q.billingType());b.setInvoiceRequired(q.invoiceRequired());b.setChangeSequence(b.getChangeSequence()+1);corporate.flush();return response(b);}
    public BookingResponses.Corporate cancel(UUID actor,UUID id,BookingRequests.Action q){var b=lock(actor,id);booking.cancel(actor,b.getReservationId(),q);return response(b);}
    @Transactional(readOnly=true) public CorporateBooking owned(UUID actor,UUID id){return corporate.findById(id).filter(b->b.getOrganizerCustomerId().equals(access.customer(actor))).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));}
    private CorporateBooking lock(UUID actor,UUID id){access.lock(corporate.restaurantId(id).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND)));return owned(actor,id);}
    private BookingResponses.Corporate response(CorporateBooking b){return new BookingResponses.Corporate(b.getId(),b.getVersion(),b.getSeriesId(),mapper.account(accounts.findById(b.getCorporateAccountId()).orElseThrow()),mapper.booking(reservations.findById(b.getReservationId()).orElseThrow()),b.getBudgetLimit(),b.getBillingType(),b.getRecurrenceType(),b.getRecurrenceRule(),b.isInvoiceRequired(),guests.findByCorporateBookingIdOrderByCreatedAtAscIdAsc(b.getId()).stream().map(mapper::guest).toList());}
}
